ALTER TABLE public.tile_requests ADD COLUMN npc_owner_id text;
ALTER TABLE public.worlds ADD COLUMN npc_land_trade_coins jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER FUNCTION public.create_tile_request(uuid,integer,integer,text,bigint) RENAME TO create_player_tile_request;
ALTER FUNCTION public.respond_tile_request(uuid,text,bigint) RENAME TO respond_player_tile_request;
REVOKE ALL ON FUNCTION public.create_player_tile_request(uuid,integer,integer,text,bigint),public.respond_player_tile_request(uuid,text,bigint) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.npc_land_response(_aggression text,_kind text,_amount bigint,_value bigint) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _kind='contest' THEN CASE WHEN _aggression='low' THEN 'accepted' ELSE 'conflict' END WHEN _aggression='low' THEN 'accepted' WHEN _aggression='medium' THEN CASE WHEN _amount>=ceil(_value*1.5) THEN 'accepted' ELSE 'countered' END ELSE CASE WHEN _amount<_value*2 THEN 'rejected' WHEN _amount< _value*3 THEN 'countered' ELSE 'accepted' END END $$;
CREATE FUNCTION public.settle_npc_tile_request(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r tile_requests%ROWTYPE; balance bigint; BEGIN SELECT * INTO r FROM tile_requests WHERE id=_id FOR UPDATE; IF r.npc_owner_id IS NULL OR r.status NOT IN('pending','countered') THEN RAISE EXCEPTION 'Invalid NPC settlement'; END IF; IF r.kind='offer' THEN SELECT COALESCE((player_data->>'coins')::bigint,500)+land_trade_coins INTO balance FROM world_members WHERE world_id=r.world_id AND user_id=r.requester_id FOR UPDATE; IF balance IS NULL OR balance<r.amount THEN RAISE EXCEPTION 'Not enough coins'; END IF; UPDATE world_members SET land_trade_coins=land_trade_coins-r.amount WHERE world_id=r.world_id AND user_id=r.requester_id; UPDATE worlds SET npc_land_trade_coins=jsonb_set(npc_land_trade_coins,ARRAY[r.npc_owner_id],to_jsonb(COALESCE((npc_land_trade_coins->>r.npc_owner_id)::bigint,0)+r.amount)) WHERE id=r.world_id; END IF; UPDATE tile_requests SET status='accepted' WHERE id=r.id; UPDATE worlds SET map_data=jsonb_set(map_data,ARRAY['tiles',r.tile_y::text,r.tile_x::text,'claimedBy'],to_jsonb(r.requester_id::text)) WHERE id=r.world_id; END $$;
CREATE FUNCTION public.create_tile_request(_world uuid,_x integer,_y integer,_kind text,_amount bigint DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w worlds%ROWTYPE; owner text; result uuid; value bigint; balance bigint; response text; BEGIN IF auth.uid() IS NULL OR NOT is_world_member(auth.uid(),_world) THEN RAISE EXCEPTION 'Not a world member'; END IF; SELECT * INTO w FROM worlds WHERE id=_world FOR UPDATE; IF _x<0 OR _y<0 OR _x>=(w.map_data->>'width')::integer OR _y>=(w.map_data->>'height')::integer THEN RAISE EXCEPTION 'Tile not found'; END IF; owner:=w.map_data->'tiles'->_y->_x->>'claimedBy'; IF owner IS NULL OR owner=auth.uid()::text THEN RAISE EXCEPTION 'Choose another owner''s tile'; END IF; IF owner !~ '^npc-[0-9]+$' THEN RETURN create_player_tile_request(_world,_x,_y,_kind,_amount); END IF; IF NOT w.enable_npcs OR substring(owner FROM 5)::integer>=w.npc_count THEN RAISE EXCEPTION 'NPC not found'; END IF; IF _kind NOT IN('offer','contest') OR _kind IS NULL THEN RAISE EXCEPTION 'Invalid request'; END IF; value:=tile_land_value(_world,_x,_y); IF _kind='offer' THEN IF _amount IS NULL OR _amount<value THEN RAISE EXCEPTION 'Minimum offer is % coins',value; END IF; SELECT COALESCE((player_data->>'coins')::bigint,500)+land_trade_coins INTO balance FROM world_members WHERE world_id=_world AND user_id=auth.uid(); IF balance IS NULL OR balance<_amount THEN RAISE EXCEPTION 'Not enough coins'; END IF; END IF; response:=npc_land_response(w.npc_aggression,_kind,_amount,value); INSERT INTO tile_requests(world_id,tile_x,tile_y,requester_id,owner_id,npc_owner_id,kind,amount,status) VALUES(_world,_x,_y,auth.uid(),auth.uid(),owner,_kind,CASE WHEN _kind='offer' THEN CASE WHEN response='countered' THEN ceil(value*CASE WHEN w.npc_aggression='medium' THEN 1.5 ELSE 3 END)::bigint ELSE _amount END END,CASE WHEN response='accepted' THEN 'pending' ELSE response END) RETURNING id INTO result; IF response='accepted' THEN PERFORM settle_npc_tile_request(result); END IF; RETURN result; END $$;
CREATE FUNCTION public.respond_tile_request(_id uuid,_action text,_amount bigint DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r tile_requests%ROWTYPE; w worlds%ROWTYPE; wid uuid; BEGIN SELECT world_id INTO wid FROM tile_requests WHERE id=_id; IF auth.uid() IS NULL OR wid IS NULL OR NOT is_world_member(auth.uid(),wid) THEN RAISE EXCEPTION 'Request not found'; END IF; SELECT * INTO w FROM worlds WHERE id=wid FOR UPDATE; SELECT * INTO r FROM tile_requests WHERE id=_id FOR UPDATE; IF r.npc_owner_id IS NULL THEN PERFORM respond_player_tile_request(_id,_action,_amount); RETURN; END IF; IF r.requester_id<>auth.uid() OR r.status<>'countered' THEN RAISE EXCEPTION 'Only the buyer can answer an NPC counteroffer'; END IF; IF w.map_data->'tiles'->r.tile_y->r.tile_x->>'claimedBy' IS DISTINCT FROM r.npc_owner_id THEN RAISE EXCEPTION 'Tile ownership has changed'; END IF; IF _action='reject' THEN UPDATE tile_requests SET status='rejected' WHERE id=_id; ELSIF _action='approve' THEN PERFORM settle_npc_tile_request(_id); ELSE RAISE EXCEPTION 'Invalid response'; END IF; END $$;
REVOKE ALL ON FUNCTION public.npc_land_response(text,text,bigint,bigint),public.settle_npc_tile_request(uuid),public.create_tile_request(uuid,integer,integer,text,bigint),public.respond_tile_request(uuid,text,bigint) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.settle_npc_tile_request(uuid) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.create_tile_request(uuid,integer,integer,text,bigint),public.respond_tile_request(uuid,text,bigint) TO authenticated,service_role;
